
import {useNavigation} from '@react-navigation/native';
import React, {useState, useEffect} from 'react';
import {TextInput} from '@react-native-material/core';
import { Button } from 'react-native-paper';
import RNPickerSelect from 'react-native-picker-select';
import DatePicker from 'react-native-date-picker';
import moment from 'moment';
import {
  View,
  Text,
  StyleSheet,
  TouchableOpacity,
  ScrollView,
} from 'react-native';

const CreditorDetailsforVRP = () => {
  const navigation = useNavigation();
  const [firstName, setFirstName] = useState('');
  const [sortCode, setSortCode] = useState('');
  const [accountNumber, setAccountNumber] = useState('');
  const [reference, setReference] = useState('');
  const [period, setPeriod] = useState('');
  const [perPayment, setPerPayment] = useState('');
  const [perPeriod, setPerPeriod] = useState('');
  const [isFormValid, setIsFormValid] = useState(false);
  const [currentDate, setCurrentDate] = useState(new Date().toISOString());
  const [accountNumberError, setAccountNumberError] = useState('');
  const [nameError, setNameError] = useState('');
  const [sortCodeError,setSortCodeError]=useState('');
  const [perPeriodError,setPerPeriodError]=useState('');
  const [perPaymentError,setPerPaymentError]=useState('');
  const [refError,setRefError]=useState('');
  const [open, setOpen] = useState(false);
  const [date, setDate] = useState(new Date());
  const [isDatePickerVisible, setDatePickerVisibility] = useState(false);
  const [expiryDate, setExpiryDate] = useState('');
  const showDatePicker = () => setDatePickerVisibility(true);
  const hideDatePicker = () => setDatePickerVisibility(false);

  //functions to validate all the  fields in the form.
  const handleDateChange = (date) => {
         setDatePickerVisibility(false);
         setExpiryDate(moment(date).format('YYYY-MM-DD')); // Format the date as needed
      };
    
      const validatefirstName = () => {
        if (!firstName.trim()) {
          setNameError('First name is required.');
        } else {
          setNameError('');
        }
     };
     const validateref = () => {
      if (!reference.trim()) {
        setRefError('Reference is required.');
      } else {
        setRefError('');
      }
    };
      const validateAccountNumber = () => {
        const match= /^[0-9]{8}$/;
        if (!accountNumber.trim()) {
          setAccountNumberError('Account Number is required.');
        } 
        else if (!match.test(accountNumber)){
          setAccountNumberError("Please enter a valid 8  digit account number.");
        }
        else {
          setAccountNumberError('');
        }
      };
      const validatesortCode = () => {
        const match= /^[0-9]{6}$/;
        if (!sortCode.trim()) {
          setSortCodeError('Sort Code is required.');
        } 
        else if (!match.test(sortCode)){
          setSortCodeError("Please enter a valid 6 digit account number.");
        }
        else {
          setSortCodeError('');
        }
      };
      const validateperPeriod=()=>{
        if (!perPeriod.trim()) {
          setPerPeriodError('Max Amount Per Period is required.');
          isValid = false;
        } else {
          setPerPeriodError('');
        }
      }
      const validateperPayment=()=>{
        if (!perPayment.trim()) {
          setPerPaymentError('Max Amount Per Payment is required.');
          isValid = false;
        } else if (parseFloat(perPayment) >= parseFloat(perPeriod)) {
          setPerPaymentError('Max Amount Per Payment must be less than Max Amount Per Period.');
          isValid = false;
        } else {
          setPerPaymentError('');
        }
      }
  useEffect(() => {
    const calculateExpiryDate = () => {
      const currentDate = new Date();
      const expiryDate = new Date(currentDate);
      expiryDate.setFullYear(expiryDate.getFullYear() + 2);

      const formattedDay = ('0' + expiryDate.getDate()).slice(-2);
      const formattedMonth = ('0' + (expiryDate.getMonth() + 1)).slice(-2);
      const formattedYear = expiryDate.getFullYear();

      const formattedExpiryDate = `${formattedYear}-${formattedMonth}-${formattedDay}`;
      setExpiryDate(formattedExpiryDate);
    };

    calculateExpiryDate();
  }, []);
  //to disable proceed to pay button
  useEffect(() => {
    // Check if all required fields are filled
    const isValid =
      !!firstName &&
      !!sortCode &&
      !!accountNumber &&
      !!reference &&
      !!period &&
      !!perPayment &&
      !!perPeriod &&
      !!expiryDate;
    setIsFormValid(isValid);
  }, [
    firstName,
    sortCode,
    accountNumber,
    reference,
    period,
    perPayment,
    perPeriod,
    expiryDate,
  ]);
  //passing form data to VRP CONSENT
  const handleSubmit = () => {
    const formData = {
      firstName,
      sortCode,
      accountNumber,
      reference,
      period,
      perPeriod,
      perPayment,
      expiryDate,currentDate
    };

    console.log('Form submitted:', formData);

    navigation.navigate('Review Creditor', {formData});
  };

  return (
      <ScrollView contentContainerStyle={styles.container}>
      <Text style={styles.title}>Sweeping Transfer Setup</Text>

      <View style={styles.formContainer}>
      <TextInput
        variant="outlined"
        label="Payee Name"
        style={styles.input}
        value={firstName}
        onChangeText={setFirstName}
        onBlur={validatefirstName}
      />
      {nameError && <Text style={styles.error}>{nameError}</Text>}

      <TextInput
        variant="outlined"
        label="Account Number"
        style={{ borderBottomWidth: 2, borderBottomColor: '#ccc', marginBottom: 10, paddingVertical: 12, paddingHorizontal: 16, fontSize: 16 }}
        onChangeText={setAccountNumber}
        value={accountNumber.toString()}
        onBlur={validateAccountNumber}
      />

      {accountNumberError ? (
        <Text style={styles.error}>{accountNumberError}</Text>
      ) : null}
        <TextInput
          variant="outlined"
          label="Sort Code"
          style={styles.input}
          keyboardType='default'
          onChangeText={setSortCode}
          value={sortCode.toString()}
          onBlur={validatesortCode}
        />
        {sortCodeError && <Text style={styles.error}>{sortCodeError}</Text>}

        <TextInput
          variant="outlined"
          label="Reference"
          style={styles.input}
          onChangeText={setReference}
          onBlur={validateref}
          value={reference}
        />
         {refError && <Text style={styles.error}>{refError}</Text>}
        <Text style={styles.title}>Payment Terms</Text>

        <View style={styles.pickerContainer}>
          <RNPickerSelect
            onValueChange={value => setPeriod(value)}
            items={[
              {label: 'Week', value: 'Week'},
              {label: 'Month', value: 'Month'},
              {label: 'Year', value: 'Year'},
            ]}
            value={period}
            placeholder={{label: 'Select period type', value: null}}
          />
        </View>

        <View style={styles.line}></View>
        <TextInput
          variant="outlined"
          label="Max Amount Per Period"
          style={styles.input}
          onBlur={validateperPeriod}
          keyboardType="numeric" 
          onChangeText={setPerPeriod}
          value={perPeriod.toString()}
        />
        {perPeriodError&& <Text style={styles.error}>{perPeriodError}</Text>}

        <TextInput
          variant="outlined"
          label="Max Amount Per Payment"
          style={styles.input}
          onBlur={validateperPayment}
          keyboardType="numeric" 
          onChangeText={setPerPayment}
          value={perPayment}
        />
         {perPaymentError&& <Text style={styles.error}>{perPaymentError}</Text>}
        <TouchableOpacity onPress={showDatePicker}>
        <TextInput
          style={styles.input}
          editable={false}
          placeholder="Select Expiry Date"
          value={expiryDate.toString() || 'Select Expiry Date'}
        />
      </TouchableOpacity>
      <DatePicker
        modal
        open={isDatePickerVisible}
        date={expiryDate ? new Date(expiryDate) : new Date()}
        onConfirm={handleDateChange}
        onCancel={hideDatePicker}
        mode="date"
        minimumDate={new Date()}
      />
    
      </View>

      <TouchableOpacity
        onPress={handleSubmit}
        style={[styles.button, {opacity: isFormValid ? 1 : 0.5}]}
        activeOpacity={isFormValid ? 0.8 : 1}
        disabled={!isFormValid}>
        <Text style={styles.buttonText}>Proceed To Pay</Text>
      </TouchableOpacity>
    </ScrollView>
  );
};

const styles = StyleSheet.create({
  container: {
    flexGrow: 1,
    backgroundColor: '#fff',
    padding: 20,
    alignItems: 'center',
    justifyContent: 'center',
  },
  pickerContainer: {
    borderWidth: 1,
    width: '92%',
    borderRadius: 5,
    position: 'center',
    alignSelf: 'center',
    marginBottom: 15,
  },
  line: {
    borderBottomWidth: 2,
    borderBottomColor: '#ccc',
    marginBottom: 10,
  },
  title: {
    fontSize: 20,
    fontWeight: 'bold',
    textAlign: 'center',
    color: 'black',
    marginBottom: 15,
  },
  formContainer: {
    width: '100%',
  },
  input: {
    borderBottomWidth: 2,
    borderBottomColor: '#ccc',
    marginBottom: 10,
    paddingVertical: 12,
    paddingHorizontal: 16,
    fontSize: 16,
  },
  button: {
    backgroundColor: '#5a287d',
    borderRadius: 8,
    padding: 15,
    width: '100%',
    alignItems: 'center',
    marginTop: 20,
  },
  buttonText: {
    color: 'white',
    fontWeight: 'bold',
    fontSize: 18,
  },
});

export default CreditorDetailsforVRP;